const UI_KEY='clinical-compass-ui-v3';
const savedUI=JSON.parse(localStorage.getItem(UI_KEY)||'{}');
let state={role:savedUI.role||'patient',view:'home',reports:[],assessments:[],scales:[],plan:null,patients:[],patient:null,currentPatient:null,selectedScale:null,lastAssessment:null,loading:true,error:null};
function saveUI(){localStorage.setItem(UI_KEY,JSON.stringify({role:state.role}))}
function icon(n){return `<svg class="icon" aria-hidden="true"><use href="#i-${n}"></use></svg>`}
const ART_NAMES=['heart','clipboard','chart','pill','chat','plan','doctor','shield','bell','user','phone'];
const customArt=new Set();
function art(name,cls=''){const src=customArt.has(name)?`assets/medsi/${name}.png`:`assets/icons/${name}.svg`;return `<img class="art ${cls}" src="${src}" alt="" aria-hidden="true" draggable="false">`}
function probeCustomArt(){const names=ART_NAMES.flatMap(name=>[name,`glass-${name}`]);let left=names.length;const done=()=>{if(--left===0&&customArt.size)render()};names.forEach(name=>{const image=new Image();image.onload=()=>{customArt.add(name);done()};image.onerror=done;image.src=`assets/medsi/${name}.png`})}
function fmtDate(x){return new Intl.DateTimeFormat('ru-RU',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}).format(new Date(x))}
function latest(){return state.reports[0]||null}
function scaleById(id){return state.scales.find(scale=>scale.id===id)}
function lastScaleResult(id){return state.assessments.find(result=>result.scale_id===id)}
function esc(value=''){const node=document.createElement('div');node.textContent=value;return node.innerHTML}
function toast(text){const node=document.querySelector('#toast');node.textContent=text;node.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>node.classList.remove('show'),2400)}
async function api(path,options={}){const response=await fetch(path,{...options,headers:{'Content-Type':'application/json','X-Demo-Role':state.role,...options.headers}});if(!response.ok){let message='Ошибка сервера';try{message=(await response.json()).detail||message}catch{}throw new Error(message)}return response.status===204?null:response.json()}
async function loadState(){state.loading=true;state.error=null;render();try{const [data,catalogue]=await Promise.all([api('/api/state'),api('/api/scales')]);state.scales=catalogue.scales;if(state.role==='patient'){state.patient=data.patient;state.currentPatient=data.patient;state.reports=data.reports;state.assessments=data.assessments;state.plan=data.plan;state.patients=[]}else{state.patients=data.patients;state.patient=null;state.currentPatient=null;state.reports=[];state.assessments=[];state.plan=null}state.loading=false;render()}catch(error){state.loading=false;state.error=error.message;render()}}
async function openPatient(id){state.loading=true;state.view='patient';render();try{const data=await api(`/api/patients/${id}`);state.currentPatient=data.patient;state.reports=data.reports;state.assessments=data.assessments;state.plan=data.plan;await api(`/api/patients/${id}/review`,{method:'POST'});state.loading=false;render()}catch(error){state.loading=false;state.error=error.message;render()}}
function shell(content,active='home',options={}){const doctor=state.role==='doctor';const unread=doctor?state.patients.reduce((sum,p)=>sum+(p.unread_messages||0),0):(state.unreadMessages||0);const hasAlert=doctor?(state.alerts||[]).some(a=>a.status!=='acknowledged')||state.patients.some(p=>p.pending_signals||(p.latest_scale_alert&&!p.latest_scale_reviewed)||(p.latest_urgent&&!p.latest_report_reviewed)):(state.tasks||[]).some(t=>t.status==='pending');const name=doctor?'Елена Крылова':state.patient?.name?.split(' ')[0]||'Анастасия';const nav=[['nav-home','home',doctor?'Пациенты':'Главная'],doctor?['nav-book','knowledge','Знания']:['nav-chart','progress','Динамика'],['nav-plan','plan',doctor?'Планы':'Мой план'],['nav-chat','messages','Связь'],['nav-user','profile','Профиль']];return `<div class="app-shell"><aside class="desktop-sidebar"><div class="brand"><span class="brand-mark">${icon('heart')}</span><span>Клинический<br>компас</span></div><nav class="side-nav">${nav.map(([i,v,l])=>`<button class="side-link ${active===v?'active':''}" data-view="${v}">${icon(i)}<span>${l}</span>${v==='messages'&&unread?`<i class="nav-count">${unread}</i>`:''}</button>`).join('')}</nav><div class="side-bottom">PHQ-9 и GAD-7 — скрининговые инструменты. Результат не является диагнозом, решение принимает врач.</div></aside><main class="main ${options.tint?'main-tint':''}"><header class="topbar"><button class="identity" data-view="profile" aria-label="Открыть профиль"><span class="avatar avatar-round">${doctor?'ЕК':'А'}<i class="verified">${icon('check')}</i></span><span class="identity-name"><small>${doctor?'Кабинет врача':'Кабинет пациента'}</small><b>${esc(name)}</b></span>${icon('chevron')}</button><div class="top-actions"><button class="icon-btn" data-view="messages" aria-label="Сообщения">${icon('message')}${unread?'<i class="dot dot-teal"></i>':''}</button><button class="icon-btn" data-view="${doctor?'home':'plan'}" aria-label="Уведомления">${icon('bell')}${hasAlert?'<i class="dot"></i>':''}</button><button class="role-switch" id="role-switch" title="Демо-режим: переключить кабинет">${doctor?'Пациент':'Врач'}</button></div></header>${options.top||''}<div class="sheet">${content}<!--/sheet--></div></main><nav class="bottom-nav">${nav.map(([i,v,l])=>`<button class="nav-item ${active===v?'active':''}" data-view="${v}"><span class="nav-glyph">${icon(i)}${v==='messages'&&unread?'<i class="nav-dot"></i>':''}</span><span>${l}</span></button>`).join('')}</nav></div>`}
function loadingView(){return shell(`<article class="card empty"><span class="status-orb">${icon('heart')}</span><h3>Загружаем данные</h3><p>Связываемся с локальным сервером…</p></article>`,state.view==='patient'?'home':state.view)}
function errorView(){return shell(`<article class="card empty"><span class="status-orb">${icon('bell')}</span><h3>Не удалось получить данные</h3><p>${esc(state.error)}</p><button class="btn btn-secondary" id="retry">Повторить</button></article>`,'home')}
function patientHome(){const report=latest();const last=state.assessments[0];const pending=(state.tasks||[]).filter(task=>task.status==='pending').length;const unread=state.unreadMessages||0;const adherence=state.adherence||{};const promo=[['glass-clipboard','Опросники PHQ-9 и GAD-7','assessments'],['glass-chat','Врач на связи','messages'],['glass-plan','План лечения','plan'],['glass-chart','Динамика состояния','progress']];const top=`<div class="promo-strip">${promo.map(([image,label,view])=>`<button class="promo-tile" data-view="${view}"><span>${label}</span>${art(image,'promo-art')}</button>`).join('')}<a class="promo-tile promo-sos" href="tel:112"><span>Экстренная помощь 112</span>${art('glass-phone','promo-art')}</a></div>`;const mini=(view,glyph,label,badge,search)=>`<button class="mini-tile" data-view="${view}" data-search="${search}"><span class="mini-icon">${icon(glyph)}${badge?`<i class="count">${badge}</i>`:''}</span><b>${label}</b></button>`;return shell(`<label class="search-bar">${icon('search')}<input id="home-search" type="search" placeholder="Поиск по разделам" autocomplete="off"></label><p class="locate">${icon('locate')}<span>${esc(state.patient?.note||'Наблюдение у врача')}</span></p><div class="tile-grid"><button class="tile tile-tall" data-view="report" data-search="самоотчёт настроение тревога сон"><b>Самоотчёт</b><span>${report?'Отчёт у врача. Обновите, если что-то изменится':'Как вы себя чувствуете сегодня?'}</span>${art('heart','tile-art')}</button><button class="tile" data-view="assessments" data-search="опросники phq-9 gad-7 шкалы тест"><b>Опросники</b><span>${last?`${scaleById(last.scale_id)?.name||''}: ${last.total} баллов`:'PHQ-9 и GAD-7'}</span>${art('clipboard','tile-art')}</button><button class="tile" data-view="progress" data-search="динамика графики результаты"><b>Динамика</b><span>${state.assessments.length?`${state.assessments.length} результатов`:'Баллы во времени'}</span>${art('chart','tile-art')}</button></div><div class="mini-grid">${mini('plan','list','Мой план',pending,'план задачи назначения')}${mini('plan','pill','Терапия','','терапия лекарства приём препарат')}${mini('messages','message','Связь',unread,'связь сообщения чат врач')}</div><div class="content-columns"><section class="section"><div class="section-head"><h2>Сегодня</h2><button class="text-btn" data-view="progress">Подробнее ${icon('chevron')}</button></div><article class="card today-card"><div class="status-line">${art(report?'shield':'bell','status-art')}<div><strong>${report?'Состояние отмечено':'Нужна ваша отметка'}</strong><p>${report?fmtDate(report.created_at):'Врач увидит результат сразу после отправки'}</p></div></div><div class="metric-row"><div class="metric"><b>${report?report.mood:'—'}</b><span>настроение</span></div><div class="metric"><b>${report?report.anxiety:'—'}</b><span>тревога</span></div><div class="metric"><b>${report?report.sleep:'—'}</b><span>сон</span></div></div><button class="btn btn-secondary btn-wide" data-view="report">${icon(report?'edit':'plus')} ${report?'Обновить отчёт':'Заполнить отчёт'}</button></article></section><section class="section"><div class="section-head"><h2>Лечащий врач</h2></div><article class="doctor-card">${art('doctor','doctor-art')}<div><b>Елена Крылова</b><span>Лечащий врач · на связи</span></div><button class="btn btn-primary" data-view="messages">${icon('message')} Написать</button></article></section></div>`,'home',{tint:true,top})}
function reportForm(){const report=latest()||{};const scale=(name,current)=>`<div class="scale">${[1,2,3,4,5].map(value=>`<input id="${name}-${value}" type="radio" name="${name}" value="${value}" ${Number(current)===value?'checked':''} required><label for="${name}-${value}">${value}</label>`).join('')}</div>`;return shell(`<div class="page-head"><button class="back" data-view="home">${icon('chevron')}</button><h2>Самоотчёт</h2><p>Отметьте, как вы чувствуете себя сегодня</p></div><form class="form-card" id="report-form"><div class="field"><label>Настроение</label><small>1 — очень плохое, 5 — отличное</small>${scale('mood',report.mood)}</div><div class="field"><label>Уровень тревоги</label><small>1 — почти нет, 5 — очень сильная</small>${scale('anxiety',report.anxiety)}</div><div class="field"><label>Качество сна</label><small>1 — очень плохое, 5 — отличное</small>${scale('sleep',report.sleep)}</div><div class="field"><label for="comment">Что ещё важно сообщить врачу?</label><textarea id="comment" name="comment" rows="4">${esc(report.comment||'')}</textarea></div><label class="check-row"><input type="checkbox" name="urgent"><span><b>Мне нужна срочная связь с врачом</b><br>Отметьте при резком ухудшении состояния</span></label><button class="btn btn-primary btn-wide" type="submit" style="margin-top:20px">Передать врачу ${icon('arrow')}</button></form>`,'home')}
function assessmentsView(){return shell(`<div class="page-head"><button class="back" data-view="home">${icon('chevron')}</button><h2>Опросники</h2><p>Стандартизированная оценка симптомов за последние две недели</p></div><div class="grid assessment-cards">${state.scales.map(scale=>{const result=lastScaleResult(scale.id);return `<article class="card assessment-card"><div class="scale-logo">${scale.name}</div><div><h3>${esc(scale.title)}</h3><p>${esc(scale.description)}</p></div>${result?`<div class="score-line"><b>${result.total}/${scale.max_score}</b><span>${esc(result.severity)}</span></div>`:'<div class="score-line"><span>Ещё не пройден</span></div>'}<button class="btn btn-secondary btn-wide" data-scale="${scale.id}">${result?'Пройти повторно':'Начать'}</button><details><summary>Источники и использование</summary><p>Русскоязычная версия валидирована. Инструмент находится в открытом использовании. Результат поддерживает оценку врача и не устанавливает диагноз.</p><a href="${scale.source.validation}" target="_blank" rel="noreferrer">Исследование валидации</a></details></article>`}).join('')}</div>`,'home')}
function assessmentForm(){const scale=state.selectedScale;return shell(`<div class="page-head"><button class="back" data-view="assessments">${icon('chevron')}</button><span class="badge badge-new">${scale.name}</span><h2>${esc(scale.title)}</h2><p>${esc(scale.instruction)}</p></div><form class="assessment-form" id="assessment-form">${scale.questions.map((question,index)=>`<fieldset class="question-card"><legend><span>${index+1}</span>${esc(question)}</legend><div class="answer-grid">${scale.response_options.map(option=>`<label><input type="radio" name="q${index}" value="${option.value}" required><span>${esc(option.label)}</span></label>`).join('')}</div></fieldset>`).join('')}<div class="notice notice-neutral"><b>Важно</b><br>Опросник оценивает выраженность симптомов и не является самостоятельным диагнозом.</div><button class="btn btn-primary btn-wide" type="submit">Рассчитать и передать врачу ${icon('arrow')}</button></form>`,'home')}
function assessmentResult(){const result=state.lastAssessment;const scale=scaleById(result.scale_id);return shell(`<div class="page-head"><h2>Результат сохранён</h2><p>Он уже доступен вашему лечащему врачу</p></div><article class="card result-card"><div class="result-score"><span>${scale.name}</span><b>${result.total}<small>/${scale.max_score}</small></b><p>${esc(result.severity)}</p></div><div class="notice notice-neutral">Результат — ориентир для обсуждения с врачом. Он не устанавливает диагноз и не изменяет лечение автоматически.</div>${result.alert?`<div class="crisis-card"><b>Сейчас важна непосредственная помощь</b><p>Если существует непосредственная угроза жизни или безопасности, позвоните 112 или обратитесь в ближайшее отделение экстренной помощи. Не ждите ответа в приложении.</p></div>`:''}<button class="btn btn-primary btn-wide" data-view="progress">Посмотреть динамику</button><button class="btn btn-secondary btn-wide" data-view="home" style="margin-top:10px">На главную</button></article>`,'home')}function doctorHome(){const attention=state.patients.filter(p=>(p.latest_scale_id&&!p.latest_scale_reviewed)||(p.latest_report_id&&!p.latest_report_reviewed));const urgent=state.patients.filter(p=>(p.latest_scale_alert&&!p.latest_scale_reviewed)||(p.latest_urgent&&!p.latest_report_reviewed));const first=urgent[0]||attention[0];return shell(`<div class="doctor-stats"><div class="stat-card">${art('user','stat-art')}<b>${state.patients.length}</b><span>пациента</span></div><div class="stat-card">${art('clipboard','stat-art')}<b>${attention.length}</b><span>новых данных</span></div><div class="stat-card ${urgent.length?'alert':''}">${art('bell','stat-art')}<b>${urgent.length}</b><span>требует внимания</span></div></div><div class="doctor-layout"><section><div class="search">${icon('search')}<input id="patient-search" placeholder="Поиск пациента"></div><div class="section-head"><h2>Мои пациенты</h2><span class="badge badge-new">${state.patients.length} активных</span></div><div class="patient-list">${state.patients.map(patient=>{const scaleNew=patient.latest_scale_id&&!patient.latest_scale_reviewed;const reportNew=patient.latest_report_id&&!patient.latest_report_reviewed;const critical=patient.latest_scale_alert&&!patient.latest_scale_reviewed;return `<button class="patient-card" data-patient="${patient.id}" data-name="${patient.name.toLowerCase()}"><span class="avatar">${patient.initials}</span><span><h3>${esc(patient.name)}</h3><p>${scaleNew?`${patient.latest_scale_id.toUpperCase()}: ${patient.latest_scale_total} · ${esc(patient.latest_scale_severity)}`:reportNew?'Новый самоотчёт':esc(patient.note)}</p></span><span>${critical?'<i class="badge badge-danger">Критический сигнал</i>':scaleNew||reportNew?'<i class="badge badge-new">Новое</i>':icon('chevron')}</span></button>`}).join('')}</div></section><section><div class="section-head"><h2>Требует внимания</h2></div>${first?`<article class="card"><div class="status-line"><div class="avatar">${first.initials}</div><div><strong>${esc(first.name)}</strong><p>${first.latest_scale_alert?'Ответ в опроснике требует проверки':'Получены новые данные'}</p></div></div>${first.latest_scale_id?`<div class="report-values"><div class="report-value"><b>${first.latest_scale_id.toUpperCase()}</b><span>шкала</span></div><div class="report-value"><b>${first.latest_scale_total}</b><span>балл</span></div><div class="report-value"><b>${first.latest_scale_alert?'!':'✓'}</b><span>сигнал</span></div></div>`:''}<button class="btn btn-primary btn-wide" data-patient="${first.id}">Открыть карточку ${icon('arrow')}</button></article>`:`<article class="card empty"><span class="status-orb">${icon('check')}</span><h3>Всё просмотрено</h3><p>Новых данных пока нет</p></article>`}</section></div>`,'home')}
function assessmentSummary(){if(!state.assessments.length)return '<div class="empty"><p>Опросники ещё не заполнены</p></div>';return `<div class="assessment-summary">${state.scales.map(scale=>{const result=lastScaleResult(scale.id);if(!result)return '';return `<div class="summary-row ${result.alert?'summary-alert':''}"><div><b>${scale.name}</b><span>${fmtDate(result.created_at)}</span></div><strong>${result.total}/${scale.max_score}</strong><p>${esc(result.severity)}</p></div>`}).join('')}</div>`}
function patientDetail(){const patient=state.currentPatient;const report=latest();const alert=state.assessments.find(item=>item.alert);return shell(`<div class="page-head"><button class="back" data-view="home">${icon('chevron')}</button></div><section class="card wide"><div class="detail-header"><div class="avatar">${patient.initials}</div><div><h2>${esc(patient.name)}</h2><p>${patient.age} лет · пациент вашего списка</p></div></div><div class="info-strip"><span class="chip">Ведущий врач: вы</span><span class="chip">${esc(patient.note)}</span><span class="chip">Данные синтетические</span></div></section>${alert?`<div class="crisis-card doctor-alert section"><b>Критический сигнал в PHQ-9</b><p>Пациент выбрал ненулевой ответ на вопрос о смерти или причинении себе вреда. Требуется клиническая оценка и контакт с пациентом. Система не принимает решение о маршрутизации автоматически.</p></div>`:''}<div class="detail-grid section"><article class="card"><div class="section-head"><h3>Стандартизированная оценка</h3><span class="badge badge-new">PHQ-9 · GAD-7</span></div>${assessmentSummary()}<button class="text-btn" data-view="progress" style="margin-top:16px">Открыть динамику →</button></article><article class="card"><div class="section-head"><h3>Последний самоотчёт</h3>${report?'<span class="badge badge-new">Получен</span>':''}</div>${report?`<p class="eyebrow">${fmtDate(report.created_at)}</p><div class="report-values"><div class="report-value"><b>${report.mood}/5</b><span>настроение</span></div><div class="report-value"><b>${report.anxiety}/5</b><span>тревога</span></div><div class="report-value"><b>${report.sleep}/5</b><span>сон</span></div></div>${report.comment?`<div class="notice notice-neutral"><b>Комментарий пациента</b><br>${esc(report.comment)}</div>`:''}`:'<div class="empty"><p>Пациент ещё не отправлял отчёт</p></div>'}</article><article class="card wide"><div class="section-head"><h3>План наблюдения</h3>${state.plan?'<span class="badge badge-new">Подтверждён</span>':''}</div><form id="plan-form"><div class="field"><label for="plan">Рекомендации пациенту</label><textarea id="plan" rows="5">${esc(state.plan?.text||'Продолжить ежедневные отметки самочувствия. Повторный контакт через 7 дней.')}</textarea></div><button class="btn btn-primary" type="submit">${icon('check')} Подтвердить и отправить</button></form></article><article class="card wide"><div class="notice notice-neutral"><b>Контроль врача</b><br>Баллы шкал поддерживают клиническую оценку, но не являются диагнозом. План и маршрутизация требуют подтверждения врача.</div></article></div>`,'home')}
function planView(){const plan=state.plan;return shell(`<div class="page-head"><h2>${state.role==='doctor'?'Планы наблюдения':'Мой план'}</h2><p>${state.role==='doctor'?'Откройте карточку пациента для работы с планом':'Рекомендации вашего лечащего врача'}</p></div>${plan?`<article class="card plan-preview"><div class="section-head"><h3>${state.role==='doctor'?esc(state.currentPatient?.name||'Пациент'):'План подтверждён'}</h3><span class="badge badge-new">Актуально</span></div><p>${esc(plan.text)}</p><div class="notice notice-success">${icon('check')} Подтверждено врачом · ${fmtDate(plan.created_at)}</div></article>`:`<article class="card empty"><span class="status-orb">${icon('file')}</span><h3>План ещё не готов</h3><p>${state.role==='doctor'?'Выберите пациента на главной странице.':'Врач отправит рекомендации после просмотра ваших данных.'}</p></article>`}`,'plan')}
function chart(scale){const results=state.assessments.filter(item=>item.scale_id===scale.id).slice(0,8).reverse();if(!results.length)return `<div class="chart-empty">Нет результатов</div>`;const points=results.map((result,index)=>{const x=results.length===1?150:25+index*(250/(results.length-1));const y=125-(result.total/scale.max_score)*95;return {x,y,result}});return `<svg class="trend-chart" viewBox="0 0 300 155" role="img" aria-label="Динамика ${scale.name}"><line x1="25" y1="125" x2="275" y2="125" class="axis"/><line x1="25" y1="30" x2="25" y2="125" class="axis"/><polyline points="${points.map(p=>`${p.x},${p.y}`).join(' ')}" class="trend-line"/>${points.map(p=>`<circle cx="${p.x}" cy="${p.y}" r="5" class="trend-dot"/><text x="${p.x}" y="${p.y-10}" text-anchor="middle">${p.result.total}</text>`).join('')}<text x="25" y="145">0</text><text x="260" y="145">сейчас</text></svg>`}
function progressView(){const reports=state.reports.slice(0,5);return shell(`<div class="page-head"><h2>Динамика состояния</h2><p>Результаты опросников и ежедневные отметки</p></div><div class="grid chart-grid">${state.scales.map(scale=>`<article class="card"><div class="section-head"><div><h3>${scale.name}</h3><p class="eyebrow">${esc(scale.title)}</p></div>${lastScaleResult(scale.id)?`<b>${lastScaleResult(scale.id).total}/${scale.max_score}</b>`:''}</div>${chart(scale)}</article>`).join('')}</div><section class="section"><div class="section-head"><h2>Ежедневные отметки</h2></div>${reports.length?`<article class="card"><div class="patient-list">${reports.map(report=>`<div class="patient-card" style="cursor:default"><span class="status-orb">${icon('chart')}</span><span><h3>${fmtDate(report.created_at)}</h3><p>Настроение ${report.mood}/5 · тревога ${report.anxiety}/5 · сон ${report.sleep}/5</p></span>${report.urgent?'<span class="badge badge-warn">Внимание</span>':''}</div>`).join('')}</div></article>`:`<article class="card empty"><p>Пока нет ежедневных отметок.</p></article>`}</section>`,'progress')}
function render(){let html;if(state.loading)html=loadingView();else if(state.error)html=errorView();else if(state.view==='report'&&state.role==='patient')html=reportForm();else if(state.view==='assessments'&&state.role==='patient')html=assessmentsView();else if(state.view==='assessment'&&state.role==='patient')html=assessmentForm();else if(state.view==='assessment-result'&&state.role==='patient')html=assessmentResult();else if(state.view==='patient'&&state.role==='doctor'&&state.currentPatient)html=patientDetail();else if(state.view==='plan')html=planView();else if(state.view==='progress')html=progressView();else html=state.role==='doctor'?doctorHome():patientHome();document.querySelector('#app').innerHTML=html;bind()}
function bind(){document.querySelector('#retry')?.addEventListener('click',loadState);document.querySelectorAll('[data-view]').forEach(element=>element.onclick=async()=>{state.view=element.dataset.view;if(state.view==='home'&&state.role==='doctor')await loadState();else render();scrollTo(0,0)});document.querySelectorAll('[data-patient]').forEach(element=>element.onclick=()=>openPatient(Number(element.dataset.patient)));document.querySelectorAll('[data-scale]').forEach(element=>element.onclick=()=>{state.selectedScale=scaleById(element.dataset.scale);state.view='assessment';render();scrollTo(0,0)});document.querySelector('#role-switch')?.addEventListener('click',async()=>{state.role=state.role==='patient'?'doctor':'patient';state.view='home';saveUI();await loadState();toast(`Открыт кабинет ${state.role==='doctor'?'врача':'пациента'}`)});document.querySelector('#report-form')?.addEventListener('submit',async event=>{event.preventDefault();const button=event.submitter;button.disabled=true;const data=new FormData(event.target);try{await api(`/api/patients/${state.patient.id}/reports`,{method:'POST',body:JSON.stringify({mood:+data.get('mood'),anxiety:+data.get('anxiety'),sleep:+data.get('sleep'),comment:data.get('comment').trim(),urgent:data.get('urgent')==='on'})});state.view='home';await loadState();toast('Отчёт сохранён и передан врачу')}catch(error){button.disabled=false;toast(error.message)}});document.querySelector('#assessment-form')?.addEventListener('submit',async event=>{event.preventDefault();const button=event.submitter;button.disabled=true;const data=new FormData(event.target);const answers=state.selectedScale.questions.map((_,index)=>Number(data.get(`q${index}`)));try{state.lastAssessment=await api(`/api/patients/${state.patient.id}/assessments`,{method:'POST',body:JSON.stringify({scale_id:state.selectedScale.id,answers})});state.assessments.unshift(state.lastAssessment);state.view='assessment-result';render();scrollTo(0,0)}catch(error){button.disabled=false;toast(error.message)}});document.querySelector('#plan-form')?.addEventListener('submit',async event=>{event.preventDefault();const text=event.target.querySelector('#plan').value.trim();if(!text)return;const button=event.submitter;button.disabled=true;try{const patientId=state.currentPatient.id;await api(`/api/patients/${patientId}/plan`,{method:'PUT',body:JSON.stringify({text})});await openPatient(patientId);toast('План подтверждён и отправлен пациенту')}catch(error){button.disabled=false;toast(error.message)}});document.querySelector('#home-search')?.addEventListener('input',event=>{const query=event.target.value.trim().toLowerCase();document.querySelectorAll('[data-search]').forEach(tile=>tile.hidden=Boolean(query)&&!(tile.dataset.search+' '+tile.textContent).toLowerCase().includes(query))});document.querySelector('#patient-search')?.addEventListener('input',event=>{const query=event.target.value.toLowerCase();document.querySelectorAll('.patient-card[data-name]').forEach(card=>card.hidden=!card.dataset.name.includes(query))})}
probeCustomArt();
render();
